import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"纵深防御","description":"","frontmatter":{"title":"纵深防御","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/defense-in-depth.md","filePath":"cs/defense-in-depth.md","lastUpdated":1789023840000}'),c={name:"cs/defense-in-depth.md"};function _(u,a,f,m,B,A){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="纵深防御" tabindex="-1">纵深防御 <a class="header-anchor" href="#纵深防御" aria-label="Permalink to &quot;纵深防御&quot;">​</a></h1><div class="epigraph"><p>纵深防御假设单层会失败：编码、CSP、沙箱、分段、检测同时在。它反对银弹，也反对无限叠加造成无法运维的疲劳。</p><footer>—— 据 NSA 对纵深的传统陈述；Saltzer and Schroeder；对照本课程各层控制</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/zero-trust-architecture">零信任</a>是一架构原则。缺口是<strong>多层同时存在</strong>如何排：每层对应哪类失败。本课收口策略图。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只 WAF、只 MFA、只加密。缺口是映射：预防、检测、响应。可用安全警告层数太多则被关。</p><h3 id="独立失败" tabindex="-1">独立失败 <a class="header-anchor" href="#独立失败" aria-label="Permalink to &quot;独立失败&quot;">​</a></h3><p>两层若同一根因（同一密钥），不是纵深。</p><p><span class="marginnote">Saltzer。TCB 最小化下一课防止纵深变成巨大不可审 TCB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按 CIA 与杀伤链映射已讲控制。下一课 TCB 最小化。</p>',12)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%E9%A2%84%E9%98%B2%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20RESP%5B%22%E5%93%8D%E5%BA%94%22%5D%0A%20%20PRE%20--%3E%20IND%5B%22%E5%B1%82%E5%BA%94%E7%8B%AC%E7%AB%8B%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>零信任是一层策略；纵深是多失败模式。TCB 下一课限制信任计算基体积。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有产品堆进去。TCB 最小化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>零信任不取消其他层。</li><li>层必须独立失败模式。</li><li>太多层会被人关掉。</li><li>下一课 TCB 最小化。</li><li>出处：Saltzer and Schroeder；NSA 纵深陈述。</li></ul>',8))])}const S=i(c,[["render",_]]);export{T as __pageData,S as default};
